// Creates separate comment-updated copies; final file hashes still require audit.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {methodSpan}=require('./prepare-material-repair-candidates-20261101.cjs');
const repo=path.resolve(__dirname,'..'),work='D:/Codex-iflytek-decompilation-repair-20261101',hash=b=>crypto.createHash('sha256').update(b).digest('hex');
function main(){const auditFile=path.join(repo,'decompilation-repair-2026-11-01/audit/MATERIAL-SEMANTIC-REVIEW.json'),auditBytes=fs.readFileSync(auditFile),audit=JSON.parse(auditBytes),old=JSON.parse(fs.readFileSync(path.join(work,'manual-material/candidates.json')));if(audit.status!=='PASS'||audit.score!==10||audit.methods.length!==2)throw Error('Independent semantic review required');const folder=path.join(work,'accepted-material'),results=[];fs.mkdirSync(folder,{recursive:true});
 for(const a of audit.methods){const m=old.candidates.find(c=>c.descriptor===a.descriptor);if(!m||m.candidate.sha256!==a.candidate.sha256||a.verdict!=='PASS-STATIC-SEMANTIC-REVIEW')throw Error('Reviewed candidate mismatch');const b=fs.readFileSync(a.candidate.file);if(b.length!==a.candidate.bytes||hash(b)!==a.candidate.sha256)throw Error('Candidate changed');const text=b.toString('utf8'),before='NOT semantically approved.',after='Static body reconstruction reviewed by independent auditor; see decompilation-repair-2026-11-01/audit/MATERIAL-SEMANTIC-REVIEW.json.';if(text.split(before).length!==2)throw Error('Expected exactly one candidate notice');const updated=text.replace(before,after);if(updated.replace(after,before)!==text)throw Error('Unexpected source change');const name=a.descriptor.split('->')[1].split('(')[0],span=methodSpan(updated,name);if(hash(updated.slice(0,span.open))!==m.proof.unchangedPrefixSha256||hash(updated.slice(span.end))!==m.proof.unchangedSuffixSha256)throw Error('Outside-body bytes changed');const file=path.join(folder,path.basename(a.candidate.file));fs.writeFileSync(file,updated);results.push({descriptor:a.descriptor,logicalPath:m.logicalPath,baseline:m.baseline,reviewedCandidate:a.candidate,finalCopy:{file,sha256:hash(updated),bytes:Buffer.byteLength(updated)},onlyChange:{before,after},outsideBodyUnchanged:true});}
 const report={schemaVersion:1,status:'COMMENT-UPDATED-COPIES-REQUIRE-EXACT-FINAL-AUDIT',semanticReview:{file:'audit/MATERIAL-SEMANTIC-REVIEW.json',sha256:hash(auditBytes)},generatorSha256:hash(fs.readFileSync(__filename)),results};fs.writeFileSync(path.join(folder,'PREPROMOTION.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(results.map(r=>({file:r.finalCopy.file,sha256:r.finalCopy.sha256}))));}
